const form = document.querySelector('#form-busca');
const curso = document.querySelector('#curso');
const resultado = document.querySelector('#resultado');

form.addEventListener('submit', async (evento) => {
  evento.preventDefault();
  const url = `http://localhost:3000/alunos?curso=${encodeURIComponent(curso.value)}`;
  const resposta = await fetch(url);
  const alunos = await resposta.json();

  resultado.textContent = '';
  alunos.forEach((aluno) => {
    const li = document.createElement('li');
    li.textContent = aluno.nome;
    resultado.appendChild(li);
  });
});

const campoUrl = document.querySelector('#url');
const botao = document.querySelector('#analisar');

botao.addEventListener('click', () => {
  const url = new URL(campoUrl.value);
  document.querySelector('#protocolo').textContent = url.protocol;
  document.querySelector('#host').textContent = url.hostname;
  document.querySelector('#caminho').textContent = url.pathname;
  document.querySelector('#query').textContent = url.search;
});

const alunos = [
  { id: 1, nome: 'Ana' },
  { id: 2, nome: 'Bruno' },
  { id: 3, nome: 'Carla' },
];
const lista = document.querySelector('#lista');

alunos.forEach((aluno) => {
  const li = document.createElement('li');
  const link = document.createElement('a');
  link.href = `detalhe.html?id=${aluno.id}`;
  link.textContent = aluno.nome;
  li.appendChild(link);
  lista.appendChild(li);
});
